<style>
/* token rides 480 (960 units) = 360 here; each gate lights as it passes */
  .token { animation: ride 1400ms var(--ease-stage) both; }
  @keyframes ride { to { translate: 360px 0; } }
  .gate { transform-box: fill-box; transform-origin: center; animation: gate 150ms var(--ease-out) both; }
  .g1 { animation-delay: 460ms; } .g2 { animation-delay: 690ms; } .g3 { animation-delay: 880ms; } .g4 { animation-delay: 1150ms; }
  @keyframes gate { from { scale: 0.6; opacity: 0; } }
  .rollers { animation: roll 1800ms linear both; }
  @keyframes roll { from { translate: -29.25px 0; } }
</style>
